// FTS index visibility toggle for EAV field forms
// Shows/hides the FTS indexing option based on primitive_kind value
document.addEventListener('DOMContentLoaded', function () {
    var ftsCard = document.getElementById('fts_card');
    if (!ftsCard) return;

    function updateFTSVisibility() {
        var primitiveInput = document.querySelector('input[name="primitive_kind"]');
        if (primitiveInput && primitiveInput.value === 'TEXT') {
            ftsCard.style.display = '';
        } else {
            ftsCard.style.display = 'none';
        }
    }

    // Initial check
    updateFTSVisibility();

    // Listen for HTMX content updates (when ui_kind changes)
    document.body.addEventListener('htmx:afterSwap', function (evt) {
        if (evt.detail.target && evt.detail.target.id === 'primitive_kind_container') {
            updateFTSVisibility();
        }
        // Also check if it's the primitive_kind_container's parent
        var container = document.getElementById('primitive_kind_container');
        if (container && container.contains(evt.detail.target)) {
            updateFTSVisibility();
        }
    });

    // Also listen for general htmx events in case the container is swapped
    document.body.addEventListener('htmx:afterSettle', function () {
        updateFTSVisibility();
    });
});
